package com.github.lucasoliveira.platform.order.controller;import com.github.lucasoliveira.platform.order.dto.*;import com.github.lucasoliveira.platform.order.service.OrderService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/orders")public class OrderController{private final OrderService service;public OrderController(OrderService service){this.service=service;}@PostMapping @ResponseStatus(HttpStatus.CREATED)public OrderResponse create(@Valid @RequestBody OrderRequest r){return service.create(r);}@GetMapping("/{id}")public OrderResponse findById(@PathVariable UUID id){return service.findById(id);}@GetMapping("/customer/{customerId}")public List<OrderResponse> findByCustomer(@PathVariable UUID customerId){return service.findByCustomer(customerId);}}
